import unreal
world=None
for candidate in unreal.ObjectIterator(unreal.World):
    if 'UEDPIE' in candidate.get_path_name():
        actors=unreal.GameplayStatics.get_all_actors_of_class(candidate,unreal.NiagaraActor)
        if actors:
            world=candidate
            break
if world is None: raise RuntimeError('PIE world with Niagara actor not found')
rt=unreal.load_object(None,'/Game/SSPR_Validation/RT_SSPR_Occupancy.RT_SSPR_Occupancy')
if rt is None: raise RuntimeError('M1 RT missing')
out=unreal.Paths.project_saved_dir()
name='M1_CLEAR_REGRESSION'
unreal.RenderingLibrary.export_render_target(world,rt,out,name)
print('M1_EXPORT='+out+name)
